package com.nanless.paperdigest.review
import com.nanless.paperdigest.data.*
import kotlinx.coroutines.runBlocking
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
import java.io.File
import java.nio.file.Files
class PendingExportsCapacityTest {
 private fun fixture(body:(File,File,File,File,File)->Unit){val p=Files.createTempDirectory("capacity-pending-").toRealPath().toFile();try{val research=File(p,"Research").apply{mkdir()};val exports=File(p,"Exports").apply{mkdir()};val cloud=File(p,"Cloud").apply{mkdir()};val device=File(p,"Device").apply{mkdir()};body(p,research,exports,cloud,device)}finally{p.deleteRecursively()}}
 private fun service(r:File,e:File,c:File,d:File)=StorageCapacity(r,e,c,d,{"2026-01-01T00:00:00Z"},{123456789L})
 @Test fun pendingCaptureReceiptAndUnknownFilesAreActuallyCountedWithoutExportDoubleCount()=fixture{p,r,e,c,d->
  File(r,"original").writeBytes(ByteArray(5));File(e,"original-export.bin").writeBytes(ByteArray(19));val pending=File(p,"PendingExports").apply{mkdir()};val op=File(pending,"synthetic-operation").apply{mkdir()};File(op,"capture.tmp").writeBytes(ByteArray(101));File(op,"producer-complete.json").writeText("explicit synthetic producer receipt");File(pending,".unknown-retained").writeBytes(ByteArray(7));val receiptLength=File(op,"producer-complete.json").length();val value=service(r,e,c,d).summary();val rows=value.getJSONArray("rows").objects().associateBy{it.getString("id")}
  assertTrue("Actual pending material row is required",rows.containsKey("pendingExports"));val row=rows.getValue("pendingExports");assertEquals("待保存准备材料",row.getString("label"));assertEquals(3L,row.getLong("fileCount"));assertEquals(108L+receiptLength,row.getLong("bytes"));assertTrue(row.getBoolean("exists"));assertEquals(1L,rows.getValue("exports").getLong("fileCount"));assertEquals(19L,rows.getValue("exports").getLong("bytes"));assertEquals(5L,rows.values.sumOf{it.getLong("fileCount")});assertEquals(132L+receiptLength,rows.values.sumOf{it.getLong("bytes")});assertTrue(File(op,"capture.tmp").isFile);assertEquals(0L,value.getJSONObject("retainedCloud").getLong("fileCount"))
 }
 @Test fun absentPendingDirectoryReportsZeroWithoutCreatingIt()=fixture{p,r,e,c,d->val pending=File(p,"PendingExports");assertFalse(pending.exists());val rows=service(r,e,c,d).summary().getJSONArray("rows").objects();val row=rows.singleOrNull{it.getString("id")=="pendingExports"};assertNotNull("Missing directory still needs an explicit measured row",row);assertEquals(0L,row!!.getLong("fileCount"));assertEquals(0L,row.getLong("bytes"));assertFalse(row.getBoolean("exists"));assertFalse(pending.exists())}
 @Test fun aSymlinkOrNonDirectoryCannotBeReportedAsZeroPendingMaterials()=fixture{p,r,e,c,d->val s=service(r,e,c,d);val outside=File(p,"outside").apply{mkdir();File(this,"keep").writeText("original")};val pending=File(p,"PendingExports");Files.createSymbolicLink(pending.toPath(),outside.toPath());assertTrue(runCatching{s.summary()}.isFailure);Files.delete(pending.toPath());pending.writeText("not a directory");assertTrue(runCatching{s.summary()}.isFailure);assertEquals("original",File(outside,"keep").readText())}
 @Test fun nestedPendingSymlinkAndOverlappingRootAreRejectedWithoutReadingTargets()=fixture{p,r,e,c,d->val pending=File(p,"PendingExports").apply{mkdir()};val outside=File(p,"outside-secret").apply{writeText("unchanged")};Files.createSymbolicLink(File(pending,"link").toPath(),outside.toPath());assertTrue(runCatching{service(r,e,c,d).summary()}.isFailure);assertEquals("unchanged",outside.readText());Files.delete(File(pending,"link").toPath());assertTrue(runCatching{service(r,e,c,File(pending,"Device"))}.isFailure)}
 @Test fun pendingMaterialsNeverBecomeExportCleanupCandidatesOrGetDeleted()=fixture{p,r,e,c,d->runBlocking{val pending=File(p,"PendingExports").apply{mkdir()};val original=File(pending,"capture.tmp").apply{writeBytes(ByteArray(90001){(it%251).toByte()})};File(pending,"producer-complete.json").writeText("preserve even unknown receipt");val bytes=original.readBytes();val s=service(r,e,c,d);var requests=0;val verifier:ExportDestinationVerifier={_,_,_->requests++;error("No export destination authorized")};val plan=s.cleanupPrepare(verifier);assertEquals(0,plan.getInt("documents"));assertEquals(0,plan.getInt("unknownEntries"));val result=s.cleanupCommit(plan.getString("planID"),verifier);assertEquals(0,result.getInt("removedFiles"));assertEquals(0,requests);assertArrayEquals(bytes,original.readBytes());assertEquals("preserve even unknown receipt",File(pending,"producer-complete.json").readText())}}
}
